const SUPPORTED = ["it", "en", "de", "es", "fr", "nl", "ru"];
function detectLang() {
  const browserLang = (navigator.language || "it").split("-")[0].toLowerCase();
  return SUPPORTED.includes(browserLang) ? browserLang : "it";
}

