  it: { creme: "Creme", frutta: "Frutta", sorbetti: "Sorbetti", speciali: "Speciali" },
  en: { creme: "Creams", frutta: "Fruit", sorbetti: "Sorbets", speciali: "Special" },
  de: { creme: "Cremes", frutta: "Frucht", sorbetti: "Sorbets", speciali: "Spezial" },
