  it: { latte: "Latte", uova: "Uova", glutine: "Glutine", frutta_secca: "Frutta secca", soia: "Soia", arachidi: "Arachidi", sesamo: "Sesamo" },
  en: { latte: "Milk", uova: "Eggs", glutine: "Gluten", frutta_secca: "Nuts", soia: "Soy", arachidi: "Peanuts", sesamo: "Sesame" },
